mapper.sql:
WHERE cs.use_yn = 'Y'
AND cs.school_level = #{schoolLevel}
AND cs.lpa_class = #{lpaClass}
AND cs.factor LIKE CONCAT('%', #{factor}, '%')

mapper.select:
/* CoachingAdminMapper.selectStrengthById */
SELECT id, school_level AS schoolLevel, lpa_class AS lpaClass, factor,
       observation, `line` AS `line`, question,
       DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i') AS updatedAt
FROM coaching_strength WHERE id = #{id}

mapper.update:
/* CoachingAdminMapper.updateStrength */
UPDATE coaching_strength
SET observation = #{observation}, `line` = #{line}, question = #{question},
    updated_by = #{updatedBy}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
/* CoachingAdminMapper.selectStrengthHistory */
SELECT history_id AS historyId, action, observation, `line` AS `line`, question,
       changed_by AS changedBy, DATE_FORMAT(changed_at, '%Y-%m-%d %H:%i:%s') AS changedAt
FROM coaching_strength_history
WHERE strength_id = #{strengthId}
ORDER BY history_id DESC

/* CoachingAdminMapper.selectStrengthHistoryById */
SELECT history_id AS historyId, strength_id AS strengthId, observation, `line` AS `line`, question
FROM coaching_strength_history WHERE history_id = #{historyId}

mapper.sql:
WHERE cm.use_yn = 'Y'
AND cm.school_level = #{schoolLevel}
AND cm.lpa_class = #{lpaClass}

    AND (cm.z_factor LIKE CONCAT('%', #{keyword}, '%')
         OR cm.x_factor LIKE CONCAT('%', #{keyword}, '%')
         OR cm.case_id  LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
/* CoachingAdminMapper.selectModerationHistoryById */
SELECT history_id AS historyId, moderation_row_id AS moderationRowId, interpretation,
       coaching1_method AS coaching1Method, coaching1_line AS coaching1Line,
       coaching2_action AS coaching2Action, coaching2_line AS coaching2Line
FROM coaching_moderation_history WHERE history_id = #{historyId}
